def count_unset_bits(n):
    if n == 0:
        return 0
    # Find the largest power of 2 less than or equal to n
    highest_power = 2 ** (n.bit_length() - 1)
    # Count unset bits in this power of 2 range
    count_in_range = highest_power // 2 + (n - highest_power + 1)
    # Recursively count unset bits for the remaining part
    return count_in_range + count_unset_bits(n - highest_power)

